def maxActivated(points):
    # Union-Find over "column x" nodes and "row y" nodes
    parent = {}

    def find(a):
        # Find root with path compression
        root = a
        while parent[root] != root:
            root = parent[root]
        while parent[a] != root:
            parent[a], a = root, parent[a]
        return root

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    # Each point links its x-node and its y-node
    for x, y in points:
        kx = ('x', x)
        ky = ('y', y)
        if kx not in parent:
            parent[kx] = kx
        if ky not in parent:
            parent[ky] = ky
        union(kx, ky)

    # Count the points in every connected component
    size = {}
    for x, y in points:
        root = find(('x', x))
        size[root] = size.get(root, 0) + 1

    # Find the two largest component sizes
    first = 0
    second = 0
    for s in size.values():
        if s > first:
            second = first
            first = s
        elif s > second:
            second = s

    # The new point can join two different components (x from one, y from the other),
    # or with one component only (other coordinate brand new). +1 for the new point.
    return first + second + 1
